 rows=[];seen=set(known)
 for family,core,a,p in groups:
  # Require core itself to be unseen, not merely a fresh courtesy prefix.
  core=normalize(core)
  assert core not in known,('known core',core)
  for text in [core,'رها لطفا '+core]:
   text=normalize(text);assert text not in seen,('duplicate',text);seen.add(text)
   options=[dict(action=a,parameters=p)]
   rows.append(dict(text=text,core=core,family=family,set='round15',policy='reject' if a=='UNKNOWN' else 'correct',action=a,parameters=p,acceptable_predictions=options))
 assert len(rows)==1000
 return rows
